cd /workspace && python3 - <<'EOF'
import json, subprocess, sys

fixtures = json.load(open('examples/checks.json'))
def same(a, b):
    if type(a) is not type(b): return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    return a == b

ok = True
for i, f in enumerate(fixtures):
    data = f.get('raw')
    if data is None:
        data = json.dumps(f['request'], separators=(',', ':'))
    p = subprocess.run([sys.executable, '-B', 'submission/main.py'], input=data.encode(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    out = p.stdout.decode()
    try:
        result = json.loads(out)
    except Exception as e:
        print(f'fixture {i}: BAD OUTPUT {out!r} {p.stderr.decode()[:500]}')
        ok = False
        continue
    if same(result, f['response']):
        print(f'fixture {i}: PASS')
    else:
        print(f'fixture {i}: MISMATCH')
        print('  got: ', json.dumps(result)[:400])
        print('  want:', json.dumps(f['response'])[:400])
        ok = False
print('ALL OK' if ok else 'FAILURES')
EOF
